  it('answers a list_conversations asked while a turn streams, before that turn\'s stream_end', async () => {
    const gate = deferred();
    const store = new InMemorySessionStore();
    const pausing: ChatOrchestrator = {
      processMessage: async () => 'hi',
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'half an answer'};
        await gate.until;
        yield {type: 'stop', stopReason: 'end_turn'};
