    await waitFor(() => listing.types().includes('connected'));
    send(first, {type: 'list_conversations'});
    await settle();

    const rows = listOf(listing.frames);
    expect(rows.at(-1)?.sessionId).toBe('conv-old');
    first.close();
    await new Promise<void>(resolve => {
      first.on('close', () => resolve());
    });

    // The id came off the list; the reconnect is the resume path the engine already ships.
    const second = connect(`${base}?sessionId=conv-old`);
    const replay = recorder(second);
